public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // k even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] adj = new ArrayList[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    return dfs(0, -1, adj, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple) {
    int time = 0;
    for (int nei : adj[node]) {
        if (nei == parent) continue;
        int sub = dfs(nei, node, adj, hasApple);
        if (sub > 0 || hasApple[nei]) {
            time += sub + 2;
        }
    }
    return time;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    // Try all possible subset sizes k from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        // The sum of the subset must be an integer
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        // Use DP with sets to store achievable sums for each subset size
        @SuppressWarnings("unchecked")
        java.util.HashSet<Integer>[] dp = new java.util.HashSet[k + 1];
        for (int i = 0; i <= k; i++) dp[i] = new java.util.HashSet<>();
        dp[0].add(0);
        for (int num : nums) {
            // Update from higher k to lower to avoid reuse of the same element
            for (int i = k; i >= 1; i--) {
                for (int prevSum : dp[i - 1]) {
                    int newSum = prevSum + num;
                    if (newSum <= target) { // prune sums larger than target
                        dp[i].add(newSum);
                    }
                }
            }
        }
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

