public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int total = 1 << k; // total number of binary strings of length k
    if (n < total) return false;

    boolean[] seen = new boolean[total];
    int mask = total - 1; // mask to keep only k bits
    int code = 0;

    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide over the string
    for (int i = k; i < n; i++) {
        // Shift left, add new bit, and mask to keep k bits
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }

    return count == total;
}

