public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n];
    int[][] dpV = new int[m][n];
    int[][] dpD = new int[m][n];
    int[][] dpAD = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]), Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0) continue;
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    stack[++top] = -1; // sentinel index
    for (int i = 0; i < n; i++) {
        while (top > 0 && heights[stack[top]] >= heights[i]) {
            int height = heights[stack[top--]];
            int width = i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top > 0) {
        int height = heights[stack[top--]];
        int width = n - stack[top] - 1;
        int area = height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int start = Math.max(0, sum - n + 1);
        int end = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = sum - i;
                res[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = sum - i;
                res[idx++] = mat[i][j];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no larger permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // overflow or invalid number
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[] digits = {'0','1','8','6','9'};
    char[] middleDigits = {'0','1','8'};
    int half = n / 2;
    boolean isOdd = (n % 2 == 1);
    // backtracking
    StringBuilder left = new StringBuilder();
    backtrack(0);
    return result;

    void backtrack(int pos) {
        if (pos == half) {
            // build full string
            StringBuilder sb = new StringBuilder();
            sb.append(left);
            if (isOdd) {
                for (char mid : middleDigits) {
                    sb.append(mid);
                    sb.append(getMirrorString(left));
                    result.add(sb.toString());
                    sb.setLength(left.length() + 1); // reset to left+mid
                }
                return;
            } else {
                sb.append(getMirrorString(left));
                result.add(sb.toString());
                return;
            }
        }
        for (char d : digits) {
            if (pos == 0 && n > 1 && d == '0') continue;
            left.append(d);
            backtrack(pos + 1);
            left.deleteCharAt(left.length() - 1);
        }
    }

    String getMirrorString(StringBuilder left) {
        StringBuilder rev = new StringBuilder();
        for (int i = left.length() - 1; i >= 0; i--) {
            char c = left.charAt(i);
            rev.append(mirror(c));
        }
        return rev.toString();
    }

    char mirror(char c) {
        switch (c) {
            case '0': return '0';
            case '1': return '1';
            case '8': return '8';
            case '6': return '9';
            case '9': return '6';
            default: return ' ';
        }
    }
